// Convert 0-based column index to spreadsheet letter (0=A, 25=Z, 26=AA, etc.)
function colLetter(idx) {
	let result = "";
	let n = idx;
	while (n >= 0) {
		result = String.fromCharCode(65 + (n % 26)) + result;
		n = Math.floor(n / 26) - 1;
	}
	return result;
}

