// Per-day Bison invoice counter. Powers nextInvoiceNumber(): each calendar
// day gets its own sequence so invoice IDs read "MMDDYYYY-N" (first of the
// day → "-1"). `day` is the MMDDYYYY key (server-local), `n` the last issued
// number for that day.
db.exec(`
	CREATE TABLE IF NOT EXISTS bison_invoice_seq (
		day TEXT PRIMARY KEY,
		n INTEGER NOT NULL DEFAULT 0
	)
`);

// One row per official invoice draft created for a load (broker draft-invoice
// flow), so the load modal can show "an approved draft exists → recipient /
// invoice #". Additive; dryRun previews never write here.
db.exec(`
	CREATE TABLE IF NOT EXISTS load_invoice_drafts (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		load_id TEXT NOT NULL,
		invoice_id TEXT,
		recipient TEXT,
		recipient_source TEXT,
		total TEXT,
		broker_name TEXT,
		order_number TEXT,
		via TEXT,
		created_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),
		created_by TEXT
	)
`);
db.exec("CREATE INDEX IF NOT EXISTS idx_load_invoice_drafts_load ON load_invoice_drafts(load_id, id DESC)");

// nextInvoiceNumber(date) → "MMDDYYYY-N", incrementing per calendar day.
// Concurrency-safe: a single UPSERT atomically bumps the counter and returns
// the new value (better-sqlite3 calls are synchronous, and the UPSERT is one
// statement, so two near-simultaneous clicks can't collide on the same N).
// `date` defaults to "now" (server local) — the button-click date.
const insertInvoiceSeqStmt = db.prepare(`
	INSERT INTO bison_invoice_seq (day, n) VALUES (?, 1)
	ON CONFLICT(day) DO UPDATE SET n = n + 1
	RETURNING n
`);
// MMDDYYYY key. Houston, not server-local: this string is the visible invoice
// number on the broker PDF, the email subject, and the filename, and the VPS runs
// UTC — so an invoice raised 8:30 PM Houston on Jul 31 went out as 08012026-1,
// the wrong day AND the wrong month for broker aging terms. It also rolled the
// per-day counter at 7 PM Houston instead of midnight.
function invoiceSeqDayKey(date = new Date()) {
	const d = date instanceof Date ? date : new Date(date);
	const [y, m, day] = houstonDay(d).split("-");
	return `${m}${day}${y}`;
}

function nextInvoiceNumber(date = new Date()) {
	const day = invoiceSeqDayKey(date);
	const row = insertInvoiceSeqStmt.get(day);
	return `${day}-${row.n}`;
}

// Like nextInvoiceNumber but WITHOUT incrementing — used by dryRun/preview so a
// preview never burns a real invoice number.
const peekInvoiceSeqStmt = db.prepare("SELECT n FROM bison_invoice_seq WHERE day = ?");
function peekInvoiceNumber(date = new Date()) {
	const day = invoiceSeqDayKey(date);
	const row = peekInvoiceSeqStmt.get(day);
	return `${day}-${(row ? row.n : 0) + 1}`;
}

